def transform(value, row):
    from datetime import datetime
    if value:
        try:
            date = datetime.strptime(value, '%Y-%m-%d')
            return date.strftime('%Y%m%d')
        except ValueError:
            try:
                date = datetime.strptime(value, '%d-%m-%Y')
                return date.strftime('%Y%m%d')
            except ValueError:
                try:
                    date = datetime.strptime(value, '%m-%d-%Y')
                    return date.strftime('%Y%m%d')
                except ValueError:
                    return value
    else:
        return value

